/* ── SCM_ADM_MNU_BTN_MPG_M — 버튼 → API 매핑 · upsert · 키 MNU_ID, SHT_NM, MNU_BTN_CD (PK) · 9행 */
MERGE INTO SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T
USING (SELECT 'SCP0100' MNU_ID, 'calendar' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_SCP0100_CALENDAR_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0100' MNU_ID, 'planDate' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_SCP0100_PLAN_DATE_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0100' MNU_ID, 'report' SHT_NM, 'COLUMN_SETUP' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0100' MNU_ID, 'report' SHT_NM, 'EXCEL' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0100' MNU_ID, 'report' SHT_NM, 'MEASURE_SELECT' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0100' MNU_ID, 'report' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_SCP0100_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0100' MNU_ID, 'searchLevel' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_SCP0100_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0100' MNU_ID, 'searchLevelDetail' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_SCP0100_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0100' MNU_ID, 'site' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_SCP0100_SITE_GET' API_ID, 'Y' USE_YN FROM DUAL) S
   ON (NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~'))
 WHEN MATCHED THEN UPDATE SET T.API_ID = S.API_ID, T.USE_YN = S.USE_YN, T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = SYSDATE
      WHERE DECODE(T.API_ID, S.API_ID, 0, 1) = 1 OR DECODE(T.USE_YN, S.USE_YN, 0, 1) = 1
 WHEN NOT MATCHED THEN INSERT (MNU_ID, SHT_NM, MNU_BTN_CD, API_ID, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
      VALUES (S.MNU_ID, S.SHT_NM, S.MNU_BTN_CD, S.API_ID, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE);

