       UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_PLAN_DATE' PROC_NM, 'divisionId' COL_NM, 'VARCHAR' DATA_TP_CD, 'IN' COL_TP_CD, 1 SORT_ORD FROM DUAL
       UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_PLAN_DATE' PROC_NM, 'o_rc1' COL_NM, 'CURSOR' DATA_TP_CD, 'OUT' COL_TP_CD, 100 SORT_ORD FROM DUAL
       UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_PLAN_DATE' PROC_NM, 'programId' COL_NM, 'VARCHAR' DATA_TP_CD, 'IN' COL_TP_CD, 3 SORT_ORD FROM DUAL
       UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_SHEET_CALENDAR_3SPAN' PROC_NM, 'O_RESULT_CURSOR' COL_NM, 'PROC_RESULT' DATA_TP_CD, 'OUT' COL_TP_CD, 101 SORT_ORD FROM DUAL
       UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_SHEET_CALENDAR_3SPAN' PROC_NM, 'endYyyymmdd' COL_NM, 'VARCHAR' DATA_TP_CD, 'IN' COL_TP_CD, 2 SORT_ORD FROM DUAL
       UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_SHEET_CALENDAR_3SPAN' PROC_NM, 'o_rc1' COL_NM, 'CURSOR' DATA_TP_CD, 'OUT' COL_TP_CD, 100 SORT_ORD FROM DUAL
       UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_SHEET_CALENDAR_3SPAN' PROC_NM, 'startYyyymmdd' COL_NM, 'VARCHAR' DATA_TP_CD, 'IN' COL_TP_CD, 1 SORT_ORD FROM DUAL
       UNION ALL SELECT 'PKG_SCP0100.P_SCP0100_GET_SITE' PROC_NM, 'O_RESULT_CURSOR' COL_NM, 'PROC_RESULT' DATA_TP_CD, 'OUT' COL_TP_CD, 101 SORT_ORD FROM DUAL
