      VALUES (S.PROGRAM_ID, S.SHEET_NAME, S.COLUMN_NAME, S.COLUMN_LABEL_NAME, S.SORT_ORDER_NO, S.SMALL_CLASS_LABEL_NAME, S.LARGE_CLASS_LABEL_NAME, S.DEFAULT_FLAG, S.USER_SELECTABLE_FLAG, S.DIVISION_ID, S.VALID_YN, S.ATTRIBUTE1, S.ATTRIBUTE2, S.ATTRIBUTE3, S.ATTRIBUTE4, S.ATTRIBUTE5, S.ATTRIBUTE6, S.ATTRIBUTE7, S.ATTRIBUTE8, S.ATTRIBUTE9, S.ATTRIBUTE10, S.INPUT_TP_CD, 'admin', SYSDATE, 'admin', SYSDATE);

